func (r *GormEventRepository) updateOutputOnlyTx(ctx context.Context, tx *gorm.DB, in *eventv1.Event, paths []string) error {
	if len(paths) == 0 {
		return fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return err
	}
	{
		var existing event.Event
		// FOR UPDATE, as in updateTx: concurrent writers holding one etag
		// take turns, and only the first passes the guard.
		if err := tx.WithContext(ctx).Clauses(clause.Locking{Strength: "UPDATE"}).First(&existing, "name = ?", key).Error; err != nil {
			return err
		}
		if in.GetEtag() != "" && existing.Etag != nil && *existing.Etag != in.GetEtag() {
			return repox.ErrConflict
		}
		next := event.EventFromProto(in)
		if repox.InMask(paths, "uid") {
			existing.UID = next.UID
		}
		if repox.InMask(paths, "expire_time") {
			existing.ExpireTime = next.ExpireTime
		}
		existing.Etag = repox.Ptr(repox.NewULID())
		return event.NewEventStore(tx).Update(ctx, &existing)
	}
}

// newRow builds the row a Batch inserts for in under parent, and the
// record it stands for, named: the same resolution Create applies.
func (r *GormEventRepository) newRow(parent string, in *eventv1.Event) (*event.Event, *eventv1.Event, error) {
	parentIDs, err := repox.SplitName(parent, "calendars")
	if err != nil {
		return nil, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "calendars", "events")
		if err != nil {
			return nil, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return nil, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*eventv1.Event)
	in.Name = FormatEventName(parentIDs[0], id)
	id = rowID // keyed as Create keys it
	m := event.EventFromProto(in)
	m.ID = id
	m.Name = in.GetName()
	m.CalendarID = parentIDs[0]
	m.Etag = repox.Ptr(repox.NewULID())
	return m, in, nil
}

// insertTx writes m inside tx with the value-object rows in carries: those
// it points at first, then m, then its children.
func (r *GormEventRepository) insertTx(ctx context.Context, tx *gorm.DB, in *eventv1.Event, m *event.Event) error {
	id := m.ID
	_ = id
	if v := in.GetOrganizer(); v != nil {
		vo := event.OrganizerFromProto(v)
		vo.ID = repox.NewULID()
		if err := tx.WithContext(ctx).Create(vo).Error; err != nil {
			return err
		}
		m.OrganizerID = repox.Ptr(vo.ID)
	}
	if v1 := in.GetStart(); v1 != nil {
		n2 := event.CalendarTimeFromProto(v1)
		n2.ID = repox.NewULID()
		n2.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n2).Error; err != nil {
			return err
		}
		m.StartID = n2.ID
	}
	if v4 := in.GetEnd(); v4 != nil {
		n5 := event.CalendarTimeFromProto(v4)
		n5.ID = repox.NewULID()
		n5.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n5).Error; err != nil {
			return err
		}
		m.EndID = repox.Ptr(n5.ID)
		c := event.EventEndsCaseEnd
		m.EndsCase = &c
	}
	if v7 := in.GetRecurrence(); v7 != nil {
		n8 := event.RecurrenceFromProto(v7)
		n8.ID = repox.NewULID()
		if v9 := v7.GetUntil(); v9 != nil {
			n10 := event.CalendarTimeFromProto(v9)
			n10.ID = repox.NewULID()
			n10.EventID = id
			if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n10).Error; err != nil {
				return err
			}
			n8.UntilID = repox.Ptr(n10.ID)
			c := event.RecurrenceBoundCaseUntil
			n8.BoundCase = &c
		}
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n8).Error; err != nil {
			return err
		}
		for _, v11 := range v7.GetWeekdays() {
			n12 := event.WeekdayNumFromProto(v11)
			n12.ID = repox.NewULID()
			n12.RecurrenceID = n8.ID
			if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n12).Error; err != nil {
				return err
			}
		}
		m.RecurrenceID = repox.Ptr(n8.ID)
	}
	if v17 := in.GetOriginalStart(); v17 != nil {
		n18 := event.CalendarTimeFromProto(v17)
		n18.ID = repox.NewULID()
		n18.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n18).Error; err != nil {
			return err
		}
		m.OriginalStartID = repox.Ptr(n18.ID)
	}
	if err := event.NewEventStore(tx).Create(ctx, m); err != nil {
		return err
	}
	for _, v20 := range in.GetAlarms() {
		n21 := event.AlarmFromProto(v20)
		n21.ID = repox.NewULID()
		n21.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n21).Error; err != nil {
			return err
		}
	}
	for _, v24 := range in.GetExtensions() {
		n25 := event.ExtensionPropertyFromProto(v24)
		n25.ID = repox.NewULID()
		n25.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n25).Error; err != nil {
			return err
		}
	}
	for _, v28 := range in.GetLinks() {
		n29 := event.LinkFromProto(v28)
		n29.ID = repox.NewULID()
		n29.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n29).Error; err != nil {
			return err
		}
	}
	for _, v32 := range in.GetParticipants() {
		n33 := event.ParticipantFromProto(v32)
		n33.ID = repox.NewULID()
		n33.EventID = id
		if err := tx.WithContext(ctx).Omit(clause.Associations).Create(n33).Error; err != nil {
			return err
		}
	}
	return nil
}

// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. update_time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GormEventRepository) Delete(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	res := r.markDeleted(ctx, r.DB, key)
	if res.Error != nil {
		return repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		return repox.ErrNotFound
	}
	return nil
}

// markDeleted sets the soft-delete mark on the live row found by key
// (rowKey) through db: Delete's write, which a Batch runs inside its
// transaction.
func (r *GormEventRepository) markDeleted(ctx context.Context, db *gorm.DB, key string) *gorm.DB {
	now := time.Now()
	return db.WithContext(ctx).Model(&event.Event{}).
		Where("name = ? AND delete_time IS NULL", key).
		Updates(map[string]any{"delete_time": now, "update_time": now, "etag": repox.NewULID(), "expire_time": repox.ExpireAt(now, r.Retention)})
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GormEventRepository) Undelete(ctx context.Context, name string) (*eventv1.Event, error) {
	key, err := r.rowKey(name)
	if err != nil {
		return nil, err
	}
	res := r.DB.WithContext(ctx).Model(&event.Event{}).
		Where("name = ? AND delete_time IS NOT NULL", key).
		Updates(map[string]any{"delete_time": nil, "etag": repox.NewULID(), "expire_time": nil})
	if res.Error != nil {
		return nil, repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		if _, err := r.get(ctx, key); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, key)
}

// Purge removes the record addressed by its resource name for good.
func (r *GormEventRepository) Purge(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	_, err = r.purge(ctx, r.DB, key, name, true)
	return repox.MapGormErr(err)
}

// purgeTx removes the row found by key (rowKey) inside tx, with the
// value-object rows it owns; gorm.ErrRecordNotFound when there is no such row.
func (r *GormEventRepository) purgeTx(ctx context.Context, tx *gorm.DB, key string) error {
	var existing event.Event
	if err := tx.WithContext(ctx).Preload("Organizer").Preload("Start").Preload("End").Preload("Recurrence").Preload("Recurrence.Until").Preload("Recurrence.WeekdayNums", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).Preload("OriginalStart").Preload("Alarms", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).Preload("ExtensionProperties", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).Preload("Links", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).Preload("Participants", func(db *gorm.DB) *gorm.DB { return db.Order("id") }).First(&existing, "name = ?", key).Error; err != nil {
		return err
	}
	if err := event.NewEventStore(tx).DeleteByID(ctx, existing.ID); err != nil {
		return err
	}
	if existing.OrganizerID != nil {
		if err := tx.WithContext(ctx).Delete(&event.Organizer{}, "id = ?", *existing.OrganizerID).Error; err != nil {
			return err
		}
	}
	if d3 := existing.Start; d3 != nil {
		if err := tx.WithContext(ctx).Delete(&event.CalendarTime{}, "id = ?", d3.ID).Error; err != nil {
			return err
		}
	}
	if d6 := existing.End; d6 != nil {
		if err := tx.WithContext(ctx).Delete(&event.CalendarTime{}, "id = ?", d6.ID).Error; err != nil {
			return err
		}
	}
	if d13 := existing.Recurrence; d13 != nil {
		for i14 := range d13.WeekdayNums {
			d15 := &d13.WeekdayNums[i14]
			if err := tx.WithContext(ctx).Delete(&event.WeekdayNum{}, "id = ?", d15.ID).Error; err != nil {
				return err
			}
		}
		if err := tx.WithContext(ctx).Delete(&event.Recurrence{}, "id = ?", d13.ID).Error; err != nil {
			return err
		}
		if d16 := d13.Until; d16 != nil {
			if err := tx.WithContext(ctx).Delete(&event.CalendarTime{}, "id = ?", d16.ID).Error; err != nil {
				return err
			}
		}
	}
	if d19 := existing.OriginalStart; d19 != nil {
		if err := tx.WithContext(ctx).Delete(&event.CalendarTime{}, "id = ?", d19.ID).Error; err != nil {
			return err
		}
	}
	for i22 := range existing.Alarms {
		d23 := &existing.Alarms[i22]
		if err := tx.WithContext(ctx).Delete(&event.Alarm{}, "id = ?", d23.ID).Error; err != nil {
			return err
		}
	}
	for i26 := range existing.ExtensionProperties {
		d27 := &existing.ExtensionProperties[i26]
		if err := tx.WithContext(ctx).Delete(&event.ExtensionProperty{}, "id = ?", d27.ID).Error; err != nil {
			return err
		}
	}
	for i30 := range existing.Links {
		d31 := &existing.Links[i30]
		if err := tx.WithContext(ctx).Delete(&event.Link{}, "id = ?", d31.ID).Error; err != nil {
			return err
		}
	}
	for i34 := range existing.Participants {
		d35 := &existing.Participants[i34]
		if err := tx.WithContext(ctx).Delete(&event.Participant{}, "id = ?", d35.ID).Error; err != nil {
			return err
		}
	}
	return nil
}

// purge removes the row found by key (rowKey), named name, for good through
// db -- unless something
// still refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught again from
// the constraint itself), or, when askReferrers, a referrer in another
// database or service (r.Refs). A purge never fails, and never cascades,
// because of a referrer. gorm.ErrRecordNotFound when there is no such row.
func (r *GormEventRepository) purge(ctx context.Context, db *gorm.DB, key, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "the-protobuf-project.org/Event", name) {
		return true, nil
	}
	// A savepoint inside a caller's transaction: a foreign key the query
	// above does not know (one from another generator run) rolls back only
	// this purge.
	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		return r.purgeTx(ctx, tx, key)
	})
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GormEventRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, r.DB, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			key, err := r.rowKey(m.GetName())
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, r.DB, key, m.GetName(), true)
			switch {
			case errors.Is(err, gorm.ErrRecordNotFound):
			case err != nil:
				return res, repox.MapGormErr(err)
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GormEventRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*eventv1.Event, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*eventv1.Event, string, error) {
		return r.List(ctx, "calendars/-", in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ EventRepository = (*GormEventRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in the Unit's transaction on
// Commit.
type gormBatch struct {
	u         *repox.Unit
	db        *gorm.DB
	retention time.Duration
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *gormBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// CreateEvent queues a create and returns the name the record will have.
func (b *gormBatch) CreateEvent(parent string, in *eventv1.Event) (string, error) {
	r := &GormEventRepository{DB: b.db}
	m, named, err := r.newRow(parent, in)
	if err != nil {
		return "", err
	}
	var locks []string
	if k, ok := any(m).(interface{ NoOverlapKeys() []string }); ok {
		locks = k.NoOverlapKeys()
	}
	queueEventReferences(b.u, named, nil)
	b.u.QueueGorm(locks, func(ctx context.Context, tx *gorm.DB) error {
		return r.insertTx(ctx, tx, named, m)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Event", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateEvent queues Update; in.Etag, when set, guards it, and a guard
// that fails rolls the whole batch back.
func (b *gormBatch) UpdateEvent(in *eventv1.Event, paths []string) {
	r := &GormEventRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueEventReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Event", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getEvent)})
}

// UpdateEventWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it, and a guard that fails rolls the whole batch back.
func (b *gormBatch) UpdateEventWithOutputOnly(in *eventv1.Event, paths, outputPaths []string) {
	r := &GormEventRepository{DB: b.db}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueEventReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Event", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getEvent)})
}

// UpdateEventOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards it.
func (b *gormBatch) UpdateEventOutputOnly(in *eventv1.Event, paths []string) {
	r := &GormEventRepository{DB: b.db}
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateOutputOnlyTx(ctx, tx, in, paths)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Event", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getEvent)})
}

// DeleteEvent queues a soft delete. A record already deleted or gone is
// not an error: two batches deleting the same record must not fail each other.
func (b *gormBatch) DeleteEvent(name string) {
	r := &GormEventRepository{DB: b.db, Retention: b.retention}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueEventDelete(b.u, name, false)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.markDeleted(ctx, tx, key).Error
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Event", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getEvent)})
}

// PurgeEvent queues the record's removal for good. A record already
// gone is not an error: two batches clearing the same row must not fail each
// other.
func (b *gormBatch) PurgeEvent(name string) {
	// A record something still refers to is kept, as Purge keeps it.
	r := &GormEventRepository{DB: b.db, Refs: b.u.Conn().References}
	key, err := r.rowKey(name)
	if err != nil {
		b.u.Fail(err)
		return
	}
	keep := queueEventPurge(b.u, name)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		if *keep {
			return nil
		}
		if _, err := r.purge(ctx, tx, key, name, false); err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return err
		}
		return nil
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Event", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getEvent)})
}
